/* TB_MAIL_ACCOUNT LAST_LOGIN_DT 갱신 mail.updateMailAccountLastLogin */
UPDATE TB_MAIL_ACCOUNT
SET
    LAST_LOGIN_DT = NOW()
    , UPDATE_DT  = NOW()
WHERE ACCOUNT_ID = #{accountId}

/* TB_MAIL_ACCOUNT 자격증명 갱신 mail.updateMailAccountCredential */
UPDATE TB_MAIL_ACCOUNT
SET
    CREDENTIAL_ENC = #{credentialEnc}
    , CREDENTIAL_IV  = #{credentialIv}
    , KEY_VERSION    = #{keyVersion}
    , LAST_LOGIN_DT  = NOW()
    , UPDATE_DT      = NOW()
WHERE ACCOUNT_ID = #{accountId}

