/* TB_MAIL_SYNC_STATE 조회 mail.selectMailSyncState */
SELECT
    ACCOUNT_ID
    , FOLDER_CD
    , UID_VALIDITY
    , LAST_SYNC_UID
    , LAST_SYNC_DT
FROM TB_MAIL_SYNC_STATE
WHERE ACCOUNT_ID = #{accountId}
  AND FOLDER_CD  = #{folderCd}

mapper.insert:
/* TB_MAIL_SYNC_STATE UPSERT mail.upsertMailSyncState */
INSERT INTO TB_MAIL_SYNC_STATE (
    ACCOUNT_ID, FOLDER_CD, UID_VALIDITY, LAST_SYNC_UID, LAST_SYNC_DT
) VALUES (
    #{accountId}, #{folderCd}, #{uidValidity}, #{lastSyncUid}, NOW()
)
ON DUPLICATE KEY UPDATE
    UID_VALIDITY  = VALUES(UID_VALIDITY),
    LAST_SYNC_UID = VALUES(LAST_SYNC_UID),
    LAST_SYNC_DT  = NOW()

