/* TB_MAIL_MSG IMAP_UID 기준 조회 mail.selectMailMsgByImapUid */
SELECT
    MAIL_ID
    , ACCOUNT_ID
    , FOLDER_CD
    , IMAP_UID
FROM TB_MAIL_MSG
WHERE ACCOUNT_ID = #{accountId}
  AND FOLDER_CD  = #{folderCd}
  AND IMAP_UID   = #{imapUid}

