/* TB_MAIL_AI_ANALYSIS UPDATE(재분석 덮어쓰기) mail.updateMailAiAnalysis */
UPDATE TB_MAIL_AI_ANALYSIS
SET
    MAIL_PURPOSE_CD        = #{mailPurposeCd}
    , ACTION_REQUIRED_CD   = #{actionRequiredCd}
    , URGENCY_CD           = #{urgencyCd}
    , IMPORTANCE_CD        = #{importanceCd}
    , WORK_CATEGORY_CD     = #{workCategoryCd}
    , DUE_DT               = #{dueDt}
    , SUMMARY              = #{summary}
    , REPLY_EXPECTED_YN    = COALESCE(#{replyExpectedYn}, 'N')
    , EXPECTED_REPLY_DUE_DT = #{expectedReplyDueDt}
    , ANALYZED_DT          = NOW()
WHERE MAIL_ID = #{mailId}

mapper.select:
/* 받은메일함 KPI 집계 (조회 기간 = inbox-classified와 동일) mail.selectMailKpi */
SELECT
    COUNT(*)                                                             AS totalCount
    , SUM(CASE WHEN A.ACTION_REQUIRED_CD = '002' THEN 1 ELSE 0 END)     AS replyRequiredCount
    , SUM(CASE WHEN A.URGENCY_CD         = '001' THEN 1 ELSE 0 END)     AS urgentCount
    , SUM(CASE WHEN DATE(A.DUE_DT)       = CURDATE() THEN 1 ELSE 0 END) AS todayDueCount
FROM TB_MAIL_MSG M
    JOIN TB_MAIL_AI_ANALYSIS A ON M.MAIL_ID = A.MAIL_ID
WHERE M.ACCOUNT_ID = #{accountId}
  AND M.FOLDER_CD  = '001'
  AND M.DELETED_YN = 'N'
  AND DATE(M.MAIL_DT) >= #{startDate}
  AND DATE(M.MAIL_DT) <= #{endDate}

/* 탭별 건수 (날짜 범위 반영) mail.selectTabCounts */
SELECT 'all' AS tabType, COUNT(*) AS cnt
FROM TB_MAIL_MSG M
    JOIN TB_MAIL_AI_ANALYSIS A ON M.MAIL_ID = A.MAIL_ID
WHERE M.ACCOUNT_ID = #{accountId}
  AND M.FOLDER_CD  = '001'
  AND M.DELETED_YN = 'N'
  AND DATE(M.MAIL_DT) >= #{startDate}
  AND DATE(M.MAIL_DT) <= #{endDate}
UNION ALL
SELECT 'action' AS tabType, COUNT(*) AS cnt
FROM TB_MAIL_MSG M
    JOIN TB_MAIL_AI_ANALYSIS A ON M.MAIL_ID = A.MAIL_ID
WHERE M.ACCOUNT_ID           = #{accountId}
  AND M.FOLDER_CD            = '001'
  AND M.DELETED_YN           = 'N'
  AND DATE(M.MAIL_DT) >= #{startDate}
  AND DATE(M.MAIL_DT) <= #{endDate}
  AND A.ACTION_REQUIRED_CD  != '005'
  AND A.ACTION_COMPLETE_YN   = 'N'
UNION ALL
SELECT 'reply' AS tabType, COUNT(*) AS cnt
FROM TB_MAIL_MSG M
    JOIN TB_MAIL_AI_ANALYSIS A ON M.MAIL_ID = A.MAIL_ID
WHERE M.ACCOUNT_ID          = #{accountId}
  AND M.FOLDER_CD           = '001'
  AND M.DELETED_YN          = 'N'
  AND DATE(M.MAIL_DT) >= #{startDate}
  AND DATE(M.MAIL_DT) <= #{endDate}
  AND A.ACTION_REQUIRED_CD  = '002'

