/* ACTION_COMPLETE_YN 토글 mail.updateActionComplete */
UPDATE TB_MAIL_AI_ANALYSIS
SET
    ACTION_COMPLETE_YN = #{actionCompleteYn}
    , ACTION_COMPLETE_DT =
        NOW()
        NULL
WHERE MAIL_ID = #{mailId}

