/* TB_MAIL_FOLLOWUP 상태 변경 mail.updateMailFollowupStatus */
UPDATE TB_MAIL_FOLLOWUP
SET
    STATUS_CD  = #{statusCd}
    , UPDATE_DT = NOW()
WHERE FOLLOWUP_ID = #{followupId}

/* TB_MAIL_FOLLOWUP 자동 매칭 mail.updateFollowupMatched */
UPDATE TB_MAIL_FOLLOWUP
SET
    REPLIED_MAIL_ID = #{repliedMailId}
    , STATUS_CD     = '002'
    , UPDATE_DT     = NOW()
WHERE FOLLOWUP_ID = #{followupId}
  AND STATUS_CD   = '001'

