AND ( EXISTS ( SELECT 1 FROM TB_MAIL_MSG R WHERE R.IN_REPLY_TO = M.MSG_ID_HEADER AND R.ACCOUNT_ID = M.ACCOUNT_ID AND R.FOLDER_CD = '001' AND R.DELETED_YN = 'N' ) OR F.STATUS_CD = '002' ) AND (COALESCE(A.REPLY_EXPECTED_YN, 'N') = 'Y' OR F.FOLLOWUP_ID IS NOT NULL)
